def pull(x, t, out, expr="smirk", **kw):   # Rio reaches into the pocket at t and the object appears at t+0.08
    return A("rio", x, [[0, "relaxed"], [t, "chest"], [t + 0.08, "holdFront"]], expr, **kw)
def pr(p, x, size, at, **kw): d = {"k": "prop", "p": p, "x": x, "size": size, "up": 0, "a": [[0, 0], [at, 0], [at + 0.05, 1]]}; d.update(kw); return d
